const amounts = [450, -300, 1220, 270, 899];

function totalSpent(amounts) {
  let total = 0;
  for (const amount of amounts) {
    if (amount < 0) {
      continue;
    }
    total += amount;
  }
  return total;
}

function countAtLeast(amounts, minimum) {
  let count = 0;
  for (const amount of amounts) {
    if (amount >= minimum) {
      count++;
    }
  }
  return count;
}

function firstOverBudget(amounts, budget) {
  let running = 0;
  for (let i = 0; i < amounts.length; i++) {
    if (amounts[i] < 0) {
      continue;
    }
    running += amounts[i];
    if (running > budget) {
      return i;
    }
  }
  return -1;
}

console.log(totalSpent(amounts), countAtLeast(amounts, 500), firstOverBudget(amounts, 2000));
